from odoo import _, api, fields, models
from odoo.exceptions import UserError

# Approver that Lotoi's flows refer to by name (same criterion used by the
# Studio automations this module replaces).
APPROVER_NAME = 'Ariel Semeraro'
REIMBURSEMENT_CATEGORY = 'Reintegro empleados'


class ApprovalRequest(models.Model):
    _inherit = 'approval.request'

    # Technical names generated by Odoo Studio, kept so the data is reused.
    x_studio_char_field_2g0_1jsp9e4ep = fields.Char(string='Nuevo Texto')
    x_studio_adjuntar_archivo = fields.Binary(string='Archivos adicionales')
    x_studio_adjuntar_archivo_filename = fields.Char(
        string='Filename for x_studio_adjuntar_archivo')
    x_studio_boolean_field_5ec_1jrvqjeec = fields.Boolean(string='Origen OC')
    x_studio_estado = fields.Selection(
        [('Pagado', 'Pago'), ('Pendiente', 'Pendiente')],
        string='estado', default='Pendiente',
    )
    x_studio_estado_1 = fields.Selection(
        [('Pago', 'Pago'), ('Pendiente', 'Pendiente')],
        string='Estado', default='Pendiente',
    )
    x_studio_one2many_field_940_1jsplgfm1 = fields.One2many(
        'approval.product.line', 'approval_request_id', string='Product Line')
    x_studio_one2many_field_3nj_1jsplsjig = fields.One2many(
        'approval.product.line', 'approval_request_id', string='Product Line')
    x_studio_product_line = fields.One2many(
        'x_approval_request_line_6a5e3', 'x_approval_request_id', string='Avance de obra')
    x_studio_related_field_i5_1jtolsuit = fields.Selection(
        related='x_studio_one2many_field_940_1jsplgfm1.x_studio_medio_de_pago',
        string='Medio De Pago', readonly=True,
    )
    x_studio_related_field_3r6_1juvp20kp = fields.Char(
        related='x_studio_one2many_field_940_1jsplgfm1.x_studio_reference',
        string='Reference', readonly=True,
    )

    # ------------------------------------------------------------------
    # Replacement of the Studio automations
    # ------------------------------------------------------------------
    @api.model_create_multi
    def create(self, vals_list):
        requests = super().create(vals_list)
        requests._lotoi_update_amount()
        requests._lotoi_remove_approver_for_purchase_origin()
        requests._lotoi_notify_reimbursement()
        return requests

    def write(self, vals):
        res = super().write(vals)
        if not self.env.context.get('lotoi_skip_amount'):
            self._lotoi_update_amount()
        return res

    def _lotoi_update_amount(self):
        """Automation "Importe": the amount is the sum of the line amounts."""
        for request in self:
            total = 0.0
            for line in request.product_line_ids:
                total += (
                    line.x_studio_importe
                    or line.x_studio_importe_1
                    or line.x_studio_importe_2
                    or 0.0
                )
            if request.amount != total:
                request.with_context(lotoi_skip_amount=True).write({'amount': total})

    def _lotoi_remove_approver_for_purchase_origin(self):
        """Automation "Quitar aprobación de Ariel en solicitudes desde OC".

        The owner already approved the purchase order, so he is not asked again.
        """
        for request in self.filtered('x_studio_boolean_field_5ec_1jrvqjeec'):
            request.approver_ids.filtered(
                lambda approver: approver.user_id.name == APPROVER_NAME
            ).unlink()

    def _lotoi_notify_reimbursement(self):
        """Automation "llamar a ariel": warn the approver about new reimbursements."""
        user = self.env['res.users'].search([('name', '=', APPROVER_NAME)], limit=1)
        if not user or not user.partner_id:
            return
        for request in self.filtered(
            lambda r: r.category_id.name == REIMBURSEMENT_CATEGORY
        ):
            if user.partner_id not in request.message_partner_ids:
                request.message_subscribe(partner_ids=[user.partner_id.id])
            if not user.partner_id.email:
                continue
            url = f"{request.get_base_url()}/odoo/approval.request/{request.id}"
            self.env['mail.mail'].sudo().create({
                'subject': _('Nuevo reintegro de empleados para revisar'),
                'email_to': user.partner_id.email,
                'body_html': (
                    '<p>Hola Ariel,</p>'
                    '<p>Se creó un <strong>Reintegro de empleados</strong> '
                    'que requiere tu atención.</p>'
                    '<p style="margin:25px 0;"><a href="%s" style="background:#875A7B;'
                    'color:#ffffff;padding:12px 22px;text-decoration:none;'
                    'border-radius:4px;font-weight:bold;display:inline-block;">'
                    'Abrir Reintegro</a></p>'
                    '<p>También podés ingresar a Odoo y buscar el reintegro desde '
                    'el menú de Aprobaciones.</p><p>Saludos.</p>'
                ) % url,
            }).send()

    # ------------------------------------------------------------------
    # "Pago" button (replaces the "Enviar comprobantes" server action)
    # ------------------------------------------------------------------
    def action_lotoi_register_payment(self):
        """Send the receipts to the requester and mark the request as paid."""
        self.ensure_one()
        attachments = self.env['ir.attachment'].search([
            ('res_model', '=', 'approval.request'),
            ('res_id', '=', self.id),
        ])
        problems = []
        if self.request_status != 'approved':
            problems.append(_("la solicitud no está aprobada"))
        if not attachments:
            problems.append(_("no tiene comprobantes cargados"))
        if problems:
            raise UserError(
                _("No se puede registrar el pago porque %s.", _(" y ").join(problems))
            )
        email = self.create_uid.partner_id.email
        if email:
            self.env['mail.mail'].sudo().create({
                'subject': _('Pago realizado - %s', self.name),
                'email_to': email,
                'body_html': _(
                    '<p>Hola,</p><p>Se registró el pago de la solicitud <b>%s</b>.</p>'
                    '<p>Adjuntamos los comprobantes.</p>', self.name),
                'attachment_ids': [fields.Command.set(attachments.ids)],
            }).send()
        self.write({
            'x_studio_estado': 'Pagado',
            'x_studio_estado_1': 'Pago',
        })
        return True
